Q: Peer receiving the answer cannot see offerer’s stream until reconnect A: <p>This looks like a transceiver topology problem.</p>
<p>You are creating fixed audio/video transceivers on peer-connection creation:</p>
<pre><code>pc.current.addTransceiver(&quot;audio&quot;, { direction: &quot;sendrecv&quot; });
pc.current.addTransceiver(&quot;video&quot;, { direction: &quot;sendrecv&quot; });
</code></pre>
<p>That is fine <strong>only if those transceivers are the ones that end up in the SDP</strong>. In your case both peers appear to create their own transceivers, and then one side receives an offer that already contains two m-lines. With <code>addTransceiver</code>, the browser does not “magically” match your locally-created transceivers to the offer in the way <code>addTrack</code> often makes easier. The answerer can end up with extra local transceivers that are not represented by the two m-lines in the offer/answer exchange. Then <code>replaceTrack()</code> succeeds, but you may be replacing the sender on the wrong/unnegotiated transceiver. That explains why reconnecting fixes it: you rebuild the <code>RTCPeerConnection</code>, so the transceiver graph happens to line up differently. This is also consistent with the existing SO answer noting that the callee may have four transceivers while the SDP has only two m-lines.</p>
<p>The fix is: <strong>do not let both sides independently pre-create the same audio/video transceivers.</strong> Pick one model.</p>
<h3>Option A: use <code>addTrack()</code> for the answerer</h3>
<p>This is usually simpler.</p>
<p>The offerer creates the initial m-lines:</p>
<pre><code>const stream = await navigator.mediaDevices.getUserMedia({
  audio: true,
  video: true,
});

for (const track of stream.getTracks()) {
  pc.addTrack(track, stream);
}

await pc.setLocalDescription(await pc.createOffer());
socket.emit(&quot;description&quot;, {
  to: peerId,
  description: pc.localDescription,
});
</code></pre>
<p>Then the answerer should set the remote offer first, add its local tracks, and only then create the answer:</p>
<pre><code>await pc.setRemoteDescription(description);

if (description.type === &quot;offer&quot;) {
  const stream = await navigator.mediaDevices.getUserMedia({
    audio: true,
    video: true,
  });

  for (const track of stream.getTracks()) {
    if (!pc.getSenders().some(sender =&gt; sender.track === track)) {
      pc.addTrack(track, stream);
    }
  }

  await pc.setLocalDescription(await pc.createAnswer());

  socket.emit(&quot;description&quot;, {
    to: from,
    description: pc.localDescription,
  });
}
</code></pre>
<h3>Option B: keep transceivers, but bind tracks to the negotiated transceivers</h3>
<p>If you want to reserve audio/video slots so camera/mic can be toggled later without renegotiation, then only the offerer should create those initial transceivers. The answerer should use the transceivers created/associated from the remote offer:</p>
<pre><code>await pc.setRemoteDescription(description);

if (description.type === &quot;offer&quot;) {
  const stream = await navigator.mediaDevices.getUserMedia({
    audio: true,
    video: true,
  });

  const audioTrack = stream.getAudioTracks()[0] ?? null;
  const videoTrack = stream.getVideoTracks()[0] ?? null;

  const audioTransceiver = pc.getTransceivers()
    .find(t =&gt; t.mid !== null &amp;&amp; t.receiver.track.kind === &quot;audio&quot;);

  const videoTransceiver = pc.getTransceivers()
    .find(t =&gt; t.mid !== null &amp;&amp; t.receiver.track.kind === &quot;video&quot;);

  if (audioTransceiver) {
    audioTransceiver.direction = &quot;sendrecv&quot;;
    await audioTransceiver.sender.replaceTrack(audioTrack);
  }

  if (videoTransceiver) {
    videoTransceiver.direction = &quot;sendrecv&quot;;
    await videoTransceiver.sender.replaceTrack(videoTrack);
  }

  await pc.setLocalDescription(await pc.createAnswer());

  socket.emit(&quot;description&quot;, {
    to: from,
    description: pc.localDescription,
  });
}
</code></pre>
<p>The important part is that your <code>toggleCamera()</code> must later use the <strong>same negotiated video transceiver</strong>, not just the first transceiver whose kind is <code>&quot;video&quot;</code>:</p>
<pre><code>function getNegotiatedTransceiver(kind) {
  return pc.current.getTransceivers()
    .find(t =&gt; t.mid !== null &amp;&amp; t.receiver.track.kind === kind);
}
</code></pre>
<p>Then:</p>
<pre><code>const transceiver = getNegotiatedTransceiver(&quot;video&quot;);
await transceiver.sender.replaceTrack(newVideoTrackOrNull);
</code></pre>
<p>Using <code>replaceTrack()</code> for camera/mic switches is the right approach once the sender is on the negotiated m-line; it is specifically intended to replace the sender’s track without a full offer/answer exchange in ordinary device-swap cases.</p>
<h3>Also buffer ICE candidates</h3>
<p>ICE candidates can arrive before <code>setRemoteDescription()</code> completes; adding them too early can fail or create inconsistent behavior. Buffer them until the remote description is set: (<a href="https://dev.to/andreik/building-a-resilient-webrtc-video-call-12j4" rel="nofollow noreferrer" title="Building a Resilient WebRTC Video Call - DEV Community">DEV Community</a>)</p>
<pre><code>const pendingCandidates = [];

socket.on(&quot;ice-candidate&quot;, async ({ candidate }) =&gt; {
  if (!candidate) return;

  if (!pc.current.remoteDescription) {
    pendingCandidates.push(candidate);
    return;
  }

  await pc.current.addIceCandidate(candidate);
});

async function flushCandidates() {
  while (pendingCandidates.length) {
    await pc.current.addIceCandidate(pendingCandidates.shift());
  }
}
</code></pre>
<p>Call <code>flushCandidates()</code> immediately after <code>setRemoteDescription()</code> resolves.</p>
<h3>Do not use renegotiation/reconnect to mask this bug</h3>
<p>An ICE restart is useful when the media path is broken, but it will not fix a wrong SDP/transceiver graph. <code>restartIce()</code> triggers ICE gathering/renegotiation, but it does not magically move your track to the correct m-line.</p>
<p>For resilience, copy the article’s ladder:</p>
<ol>
<li><p>wait for a short video warm-up period;</p>
</li>
<li><p>check <code>connectionState</code>, <code>iceConnectionState</code>, and RTP byte deltas from <code>getStats()</code>;</p>
</li>
<li><p>if ICE failed but SDP is correct, try <code>pc.restartIce()</code>;</p>
</li>
<li><p>if the peer connection topology is wrong, close both peer connections and rebuild;</p>
</li>
<li><p>only one side should drive restart/recovery, otherwise both peers can race and create more SDP glare.</p>
</li>
</ol>
<p>So the practical fix is not “renegotiate after <code>replaceTrack()</code>.” The practical fix is: <strong>create exactly one audio m-line and one video m-line, make sure both peers attach their tracks to those negotiated transceivers, buffer ICE until the remote description exists, and reserve full restart only as a recovery path.</strong></p>

Q: How to get the background color of an HTML element? A: <p>You can draw a canvas element over you control, even without display it, to get the color at a specific position in you controls, if it has many colors.</p>
<p>This is a working fiddle.
<a href="https://jsfiddle.net/cdgpts9n/" rel="nofollow noreferrer">https://jsfiddle.net/cdgpts9n/</a></p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;html&gt;
&lt;head&gt;
    &lt;style&gt;
    &lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;&lt;div style="border:gray solid 2px;height:575px;width:700px;position:absolute;top:75px;right:15px;background:black;color:white;font-Family:Century SchoolBook;font-Size:18px;padding-Top:20px;" id="container101"&gt;&lt;div id="header" style="text-Align:center"&gt;ColorPicker&lt;/div&gt; 
    &lt;div id="div101" style="position:absolute;top:60px;left:100px;width:500px;height:500px;"&gt;&lt;/div&gt; 
    &lt;canvas height="500" width="500" style="position:absolute;top:60px;left:100px;display:none;" id="canva"&gt;&lt;/canvas&gt;

&lt;/div&gt;

&lt;script&gt;
    function create(r1,g1,b1,r2,g2,b2){dv101 = 
    document.querySelector("#div101");dv101.style.background = "linear-gradient(90deg, rgb("+r1+", "+g1+", "+b1+"), rgb("+r2+", "+g2+", "+b2+"))";
    var can = document.querySelector("#canva");
    var context = can.getContext("2d");
    context.rect(0, 0, 500, 500);
    var grd = context.createLinearGradient(0,0,can.width,0);
    grd.addColorStop(0, "rgb("+r1+", "+g1+", "+b1+")");
    grd.addColorStop(1, "rgb("+r2+", "+g2+", "+b2+")");
    context.fillStyle = grd;
    context.fillRect(0,0,500,500);

    dv101.onmousemove = (event) =&gt; {
        var posx = event.clientX-dv101.offsetLeft- 
        document.querySelector("#container101").offsetLeft;
        var posy = event.clientY-dv101.offsetTop- 
        document.querySelector("#container101").offsetTop;
        var data = context.getImageData(posx,posy,1,1);
        couleur = "rgb("+data.data[0]+","+data.data[1]+","+data.data[2]+")";
        document.body.style.background=couleur;
        console.log(couleur);
        return couleur;
    }; 
};create(255, 0, 0, 0, 0, 255);
var arr = new Array();
function inp(x,y){
    var input1 = document.createElement('input');
    var cont = document.querySelector("#container101");
    cont.appendChild(input1);
    arr.push(input1);
    input1.type = "text";
    input1.style = "outline:none;position:absolute;top:"+y+"px;left:"+x+"px;height:30px;width:60px;background:white;color:black;";
    input1.value = 0;
    input1.onkeydown = (event) =&gt; {

        switch(event.keyCode){

        case 38:
            input1.value++;
            create(arr[0].value, arr[1].value, arr[2].value, arr[3].value, arr[4].value,arr[5].value);
            break;

        case 40:
            input1.value--;
            create(arr[0].value, arr[1].value, arr[2].value, arr[3].value, arr[4].value,arr[5].value);
            break;
        };
    }
};inp(5,60);inp(5,110);inp(5,160);inp(610,60);inp(610,110);inp(610,160);
&lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;</code></pre>
